import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import {
  APPROVAL_PLAN,
  enableApprovalPolicy,
  inspectApprovals,
  reserveApproval,
  approvalReceipt,
  approvalObservationReady,
  completionResultReceipt,
} from "./native-approval.mjs";
import {
  createNativeScope,
  observeProjection,
  assertNativeRpc,
  NATIVE_ORIGIN,
} from "./native-rpc.mjs";
import { hydrateApprovedToolOutputs } from "./native-tool-detail.mjs";
// Raw immutable stopped events plus wire payloads generated by the exact 8d40 runtime
// projector. A later successful provider turn is simulated explicitly, never claimed observed.
const [metadata, ...events] = readFileSync(
  new URL("./native-wire/native-completion-wire.jsonl", import.meta.url),
  "utf8",
)
  .trim()
  .split("\n")
  .map(JSON.parse);
const projectId = metadata.projectId,
  coordinatorId = `project-coordinator:${projectId}`;
const fields = {
  run: "runs",
  "run-attempt": "attempts",
  node: "nodes",
  "turn-item": "turnItems",
  "runtime-request": "runtimeRequests",
  "provider-thread": "providerThreads",
  "provider-turn": "providerTurns",
  "provider-session": "providerSessions",
  subagent: "subagents",
  message: "messages",
};
function prefix(sequence, wire = false) {
  const snapshots = new Map();
  for (const e of events.filter((e) => e.sequence <= sequence)) {
    const entity = e.type.split(".")[0];
    if (!snapshots.has(e.streamId))
      snapshots.set(e.streamId, Object.fromEntries(Object.values(fields).map((k) => [k, []])));
    const p = snapshots.get(e.streamId),
      value = structuredClone(wire && e.wirePayload ? e.wirePayload : e.payload);
    if (entity === "thread") p.thread = { ...p.thread, ...value };
    else {
      const rows = p[fields[entity]],
        i = rows.findIndex((r) => r.id === value.id);
      if (wire && entity === "turn-item") delete value.threadId;
      if (i < 0) rows.push(value);
      else rows[i] = { ...rows[i], ...value };
    }
  }
  return snapshots;
}
function replay() {
  const scope = createNativeScope(projectId, true, 5),
    snapshots = prefix(32, true),
    p = snapshots.get(coordinatorId),
    run = p.runs[0];
  enableApprovalPolicy(
    scope,
    {
      schemaVersion: 2,
      authorization: "six-native-project-runs-with-exact-single-use-approvals",
      approvalPlan: structuredClone(APPROVAL_PLAN),
      maxRuns: 5,
      codex: { model: run.modelSelection.model },
      claude: { model: "claude-haiku-5-5" },
    },
    "offline-followup",
  );
  assertNativeRpc(
    NATIVE_ORIGIN,
    "projects.coordinatorStart",
    {
      projectId,
      commandId: run.userMessageId.slice(`coordinator-send:${projectId}:`.length),
      prompt: "Recorded synthetic dispatch; offline only.",
    },
    scope,
  );
  for (const p of snapshots.values()) observeProjection(scope, p);
  const candidate = inspectApprovals(scope, snapshots, 0),
    command = reserveApproval(scope, candidate);
  assertNativeRpc(NATIVE_ORIGIN, "orchestration.dispatchCommand", command, scope);
  return { scope, snapshots };
}
function hydrate(f, sequence) {
  const raw = prefix(sequence);
  f.snapshots = prefix(sequence, true);
  for (const p of f.snapshots.values()) observeProjection(f.scope, p);
  for (const [id, p] of f.snapshots) {
    const detail = hydrateApprovedToolOutputs(
      f.scope,
      p,
      (projectId, threadId, itemId) => ({
        projectId,
        threadId,
        item: raw.get(threadId).turnItems.find((i) => i.id === itemId),
      }),
      0,
    );
    assert(detail.ready);
    f.snapshots.set(id, detail.projection);
  }
  return f.snapshots.get(coordinatorId);
}
function wake(f) {
  const p = hydrate(f, 106),
    run = p.runs.find((r) => r.ordinal === 2),
    attempt = p.attempts.find((a) => a.runId === run.id);
  return { p, run, attempt };
}
function publish(f) {
  const { p, run, attempt } = wake(f);
  p.providerTurns.push({
    ...p.providerTurns[0],
    id: "simulated-next-publication",
    runAttemptId: attempt.id,
    nodeId: run.rootNodeId,
    status: "running",
  });
  observeProjection(f.scope, p);
  return { p, run, attempt };
}
test("actual completed capabilities remain discovery and compact delegate preserves exact stored child bindings", () => {
  const f = replay();
  f.snapshots = prefix(90, true);
  for (const p of f.snapshots.values()) observeProjection(f.scope, p);
  const p = f.snapshots.get(coordinatorId),
    delegate = p.turnItems.find((i) => i.toolName === "studio-code.delegate_task");
  assert.equal(delegate.outputOmitted, true);
  assert.deepEqual(Object.keys(delegate.output), ["taskId"]);
  assert.equal(delegate.threadId, undefined);
  assert.throws(() => inspectApprovals(f.scope, f.snapshots, 0), /completion task binding/);
  hydrate(f, 90);
  assert.equal(inspectApprovals(f.scope, f.snapshots, 0), null);
  assert.equal(approvalReceipt(f.scope).length, 1);
  assert(
    p.turnItems.some(
      (i) => i.toolName === "studio-code.orchestrator_capabilities" && i.status === "completed",
    ),
  );
});
test("exact runtime wire projector omits required output details for all five approved operations", () => {
  assert.deepEqual(
    metadata.cases.map((c) => c.operation),
    APPROVAL_PLAN.operations,
  );
  for (const c of metadata.cases) {
    assert.deepEqual(c.wire, { threadId: "child", messageId: "message", taskId: "task" });
    assert.equal(c.wire.childRunId, undefined);
    assert.equal(c.wire.runId, undefined);
    assert.equal(c.wire.summary, undefined);
  }
});
test("actual event prefixes hydrate before guards, then event106 defers with no grant until simulated next publication", () => {
  const f = replay();
  for (const sequence of Array.from({ length: 74 }, (_, i) => i + 33)) {
    hydrate(f, sequence);
    assert.equal(inspectApprovals(f.scope, f.snapshots, sequence), null);
    assert.equal(approvalReceipt(f.scope).length, 1);
  }
  assert.equal(approvalObservationReady(f.scope), false);
  assert.throws(
    () => completionResultReceipt(f.scope, f.snapshots.get(coordinatorId)),
    /publication incomplete/,
  );
  publish(f);
  assert.equal(inspectApprovals(f.scope, f.snapshots, 200), null);
  assert.equal(approvalObservationReady(f.scope), true);
  assert.equal(approvalReceipt(f.scope).length, 1);
});
test("exact bound missing wake publication times out and cannot settle", () => {
  const f = replay();
  wake(f);
  assert.equal(inspectApprovals(f.scope, f.snapshots, 10), null);
  assert.throws(
    () => inspectApprovals(f.scope, f.snapshots, 2011),
    /publication changed or timed out/,
  );
  assert.equal(approvalObservationReady(f.scope), false);
});
const mutations = {
  "nonnull absent backref": ({ attempt }) => {
    attempt.providerTurnId = "unpublished";
  },
  "foreign turn on wake root": ({ p, run }) => {
    p.providerTurns.push({ ...p.providerTurns[0], id: "foreign", nodeId: run.rootNodeId });
  },
  "foreign session": ({ p }) => {
    p.providerSessions[0].id = "foreign";
  },
  "wrong model": ({ run }) => {
    run.modelSelection.model = "other";
  },
  "retry attempt": ({ attempt }) => {
    attempt.reason = "retry";
  },
  "wrong root": ({ attempt }) => {
    attempt.rootNodeId = "foreign";
  },
  "wrong completion message": ({ p }) => {
    p.messages.find((m) => m.delegatedCompletion).text = "unreviewed";
  },
  "missing completion message": ({ p }) => {
    p.messages = p.messages.filter((m) => !m.delegatedCompletion);
  },
  "terminal missing turn": ({ run }) => {
    run.status = "completed";
  },
};
for (const [name, mutate] of Object.entries(mutations))
  test(`actual missing publication refuses ${name} immediately`, () => {
    const f = replay(),
      state = wake(f);
    mutate(state);
    assert.throws(() => inspectApprovals(f.scope, f.snapshots, 0), /Native approval refused/);
    assert.equal(approvalReceipt(f.scope).length, 1);
  });
test("multiple turns and changed identity cannot replace deferred wake", () => {
  const f = replay();
  wake(f);
  inspectApprovals(f.scope, f.snapshots, 0);
  const { p } = publish(f);
  p.providerTurns.push({ ...p.providerTurns.at(-1), id: "duplicate" });
  assert.throws(() => inspectApprovals(f.scope, f.snapshots, 1), /turn missing\/ambiguous/);
  const g = replay();
  wake(g);
  inspectApprovals(g.scope, g.snapshots, 0);
  const next = wake(g);
  next.attempt.id = "rebound";
  next.run.activeAttemptId = "rebound";
  assert.throws(() => inspectApprovals(g.scope, g.snapshots, 1), /wake identity changed/);
});

test("actual missing-message stage keeps one deadline through attempt, message and turn publication", () => {
  const f = replay();
  hydrate(f, 96);
  assert.equal(inspectApprovals(f.scope, f.snapshots, 10), null);
  assert.equal(approvalObservationReady(f.scope), false);
  for (const sequence of [97, 98, 99, 100, 106]) {
    hydrate(f, sequence);
    assert.equal(inspectApprovals(f.scope, f.snapshots, 100), null);
  }
  assert.throws(
    () => inspectApprovals(f.scope, f.snapshots, 2011),
    /publication changed or timed out/,
  );
  assert.equal(approvalReceipt(f.scope).length, 1);
});
for (const [name, mutate] of Object.entries({
  "wrong cohort message": (p) => {
    p.runs[1].userMessageId = "foreign";
  },
  "wrong present attempt": (p) => {
    p.attempts[1].reason = "retry";
  },
  "duplicate present attempt": (p) => {
    p.attempts.push({ ...p.attempts[1], id: "duplicate" });
  },
  "wrong present root": (p) => {
    p.nodes.find((n) => n.id === p.runs[1].rootNodeId).providerThreadId = "foreign";
  },
  "present foreign completion": (p) => {
    p.messages.push({ id: "foreign", delegatedCompletion: {} });
  },
  "tool before message": (p) => {
    p.turnItems.push({ id: "foreign", runId: p.runs[1].id, type: "dynamic_tool" });
  },
  "provider turn before message": (p) => {
    p.providerTurns.push({
      ...p.providerTurns[0],
      id: "foreign",
      runAttemptId: p.runs[1].activeAttemptId,
    });
  },
}))
  test(`actual missing-message stage refuses ${name}`, () => {
    const f = replay(),
      p = hydrate(f, 99);
    mutate(p);
    assert.throws(() => inspectApprovals(f.scope, f.snapshots, 0), /Native approval refused/);
    assert.equal(approvalReceipt(f.scope).length, 1);
  });

test("a fully observed wake turn cannot regress to the initial publication wait", () => {
  const f = replay();
  publish(f);
  assert.equal(inspectApprovals(f.scope, f.snapshots, 0), null);
  assert.equal(approvalObservationReady(f.scope), true);
  wake(f);
  assert.throws(() => inspectApprovals(f.scope, f.snapshots, 1), /published turn disappeared/);
  assert.equal(approvalReceipt(f.scope).length, 1);
});
